```python
def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"

        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return (
            bool(local)
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )

    def normalize_phone(value):
        extension = re.search(r"ext|x|#", value, flags=re.IGNORECASE)
        if extension:
            value = value[:extension.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) == 10 and digits[0] not in {"0", "1"}:
            return digits
        return ""

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError("Unsupported updated date: {!r}".format(value))

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized_rows = []

    for input_index, row in enumerate(rows):
        email = normalize_email(row["email"])
        if not valid_email(email):
            email = ""

        phone = normalize_phone(row["phone"])

        # Rows without either valid contact method are excluded entirely.
        if not email and not phone:
            continue

        normalized_rows.append({
            "input_index": input_index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
            "opted_out": is_opted_out(row["opted_out"]),
            "updated_dt": parse_updated(row["updated"]),
        })

    # Union-find handles transitive matches.
    parent = list(range(len(normalized_rows)))
    rank = [0] * len(normalized_rows)

    def find(item):
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    email_owner = {}
    phone_last_owner = {}

    for index, row in enumerate(normalized_rows):
        if row["email"]:
            previous = email_owner.get(row["email"])
            if previous is None:
                email_owner[row["email"]] = index
            else:
                union(index, previous)

        last_name_key = row["last_name"].casefold()
        if row["phone"] and last_name_key:
            key = (row["phone"], last_name_key)
            previous = phone_last_owner.get(key)
            if previous is None:
                phone_last_owner[key] = index
            else:
                union(index, previous)

    groups = {}
    for index, row in enumerate(normalized_rows):
        groups.setdefault(find(index), []).append(row)

    def pick_field(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        chosen = max(
            candidates,
            key=lambda row: (
                row["source"].casefold() == "manual",
                row["updated_dt"],
                -row["input_index"],
            ),
        )
        return chosen[field]

    results = []

    for group in sorted(
        groups.values(),
        key=lambda members: min(row["input_index"] for row in members),
    ):
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        latest_updated = max(row["updated_dt"] for row in group)

        results.append({
            "first_name": pick_field(group, "first_name"),
            "last_name": pick_field(group, "last_name"),
            "zip": pick_field(group, "zip"),
            "email": pick_field(group, "email"),
            "phone": pick_field(group, "phone"),
            "source": pick_field(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return results
